const float ANOM_CENTROIDES[168] = {0.573857f, -0.447763f, -0.268382f, -0.228981f, 2.138810f, 1.490862f, 1.632717f, 1.929626f, -0.207119f, -0.150155f, -0.397204f, 2.757768f, 1.901044f, 2.064873f, 1.572267f, -0.036940f, -0.263057f, -0.331840f, 2.067786f, 1.619694f, 1.933151f, -1.010750f, -0.434486f, -0.498501f, -0.484217f, -0.504024f, -0.551799f, -0.644538f, 0.210752f, 0.128434f, -0.190129f, -0.362239f, -0.530638f, -0.550363f, -0.630292f, -0.649620f, -0.209517f, -0.288975f, -0.335250f, -0.477741f, -0.483516f, -0.560817f, 0.510890f, 1.916372f, 1.953102f, 1.872754f, -0.145918f, 0.129111f, 0.417388f, -0.027153f, 0.090831f, 0.522818f, 0.875551f, -0.027699f, 0.243315f, 0.504380f, -0.005144f, 3.411877f, 2.746399f, 2.367331f, -0.164678f, 0.033574f, 0.256483f, 0.514832f, 1.884456f, 1.841736f, 1.694984f, -0.027789f, 0.341370f, 0.753728f, 0.080322f, -0.546487f, 0.597028f, 1.266633f, 0.090136f, 0.277198f, 0.541177f, -0.092806f, -0.071879f, 0.688665f, 1.020185f, -0.122966f, 0.028321f, 0.211858f, 1.424409f, -0.393894f, -0.500334f, -0.490935f, 2.932942f, 4.369453f, 3.443084f, 1.730637f, -0.088219f, -0.416656f, -0.606875f, 2.083315f, 3.698616f, 2.911370f, 2.889078f, -0.199446f, -0.399532f, -0.426507f, 3.531835f, 4.505758f, 3.834172f, 1.498258f, -0.604631f, -0.616561f, -0.587649f, -0.405392f, -0.470513f, -0.554214f, -1.849645f, -0.769395f, -0.642670f, -0.623717f, -0.352954f, -0.365117f, -0.420764f, 0.386812f, -0.524222f, -0.468335f, -0.456776f, -0.363246f, -0.407932f, -0.484947f, -0.538125f, -0.125701f, -0.072134f, -0.014822f, -0.484037f, -0.544783f, -0.629047f, -0.031804f, 1.714150f, 1.044005f, 0.858327f, -0.526075f, -0.539702f, -0.612222f, -0.599696f, 0.066795f, 0.020019f, -0.002089f, -0.447121f, -0.460734f, -0.527620f, 0.186102f, -0.416831f, -0.353956f, -0.323199f, 0.205857f, 0.133310f, 0.107340f, -0.424403f, -0.499306f, -0.432047f, -0.407097f, -0.239239f, -0.177501f, -0.161942f, 0.276966f, -0.410798f, -0.446572f, -0.400122f, 0.062418f, 0.013738f, -0.000802f};

// Devuelve la distancia al centroide mas cercano. Por encima de ANOM_UMBRAL
// la ventana se reporta como anomalia y se ignora la etiqueta del clasificador.
float anomalia_puntaje(const float *car) {
  float mejor = 1e30f;
  for (int k = 0; k < ANOM_K; k++) {
    float acum = 0.0f;
    for (int j = 0; j < ANOM_N_CAR; j++) {
      float z = (car[j] - ANOM_MEDIA[j]) / ANOM_DESV[j];
      float d = z - ANOM_CENTROIDES[k * ANOM_N_CAR + j];
      acum += d * d;
    }
    if (acum < mejor) mejor = acum;
  }
  return sqrtf(mejor);
}
